	using namespace noarr;

	const num_t scale = num_t(10) / num_t(n); // precompute (10 / n)

	traverser(A, B).for_each([=](auto state) {
		auto [i, j, k] = get_indices<'i', 'j', 'k'>(state);

		// Original formula: (DATA_TYPE)(i + j + (n - k)) * 10 / n;
		// We evaluate it as ((i + j + (n - k)) * scale), which is
