	// These are tunable constants; they assume reasonably large grids and
	// modern cache sizes. The runtime check below ensures correctness even
	// when (n - 2) is not divisible by these values.
	constexpr std::size_t TI = 32;
	constexpr std::size_t TJ = 32;

	const int interior_len = n - 2;
	const bool can_block =
		(interior_len > 0) &&
		(interior_len % static_cast<int>(TI) == 0) &&
		(interior_len % static_cast<int>(TJ) == 0);

