						const num_t two_center = two * center;

						const num_t lap_i =
							A[state + idx<'i'>(1)] - two_center + A[state - idx<'i'>(1)];
						const num_t lap_j =
							A[state + idx<'j'>(1)] - two_center + A[state - idx<'j'>(1)];
						const num_t lap_k =
							A[state + idx<'k'>(1)] - two_center + A[state - idx<'k'>(1)];

						const num_t lap_sum = lap_i + lap_j + lap_k;

						B[state] = center + eighth * lap_sum;
					});
				});

				// Second sweep: update A from B, with the same blocked
				// iteration pattern. At this point B contains the results
				// from the first sweep for the whole domain of this time
				// step, so this matches the original update order.
				blocked_trav.template for_dims<'I', 'J'>([&](auto tile_trav) {
					tile_trav.for_each([&](auto state) {
						using noarr::idx;

						const num_t center     = B[state];
						const num_t two_center = two * center;

						const num_t lap_i =
							B[state + idx<'i'>(1)] - two_center + B[state - idx<'i'>(1)];
						const num_t lap_j =
							B[state + idx<'j'>(1)] - two_center + B[state - idx<'j'>(1)];
						const num_t lap_k =
							B[state + idx<'k'>(1)] - two_center + B[state - idx<'k'>(1)];

						const num_t lap_sum = lap_i + lap_j + lap_k;

						A[state] = center + eighth * lap_sum;
					});
				});
			});
