	// Using pre-constructed states avoids reconstructing them in every stencil evaluation.
	constexpr auto di = noarr::idx<'i'>(1);
	constexpr auto dj = noarr::idx<'j'>(1);
	constexpr auto dk = noarr::idx<'k'>(1);

	// Stencil coefficients, algebraically equivalent to the original formulation:
	// Original update:
	//   lap_i = A[i+1,j,k] - 2*A[i,j,k] + A[i-1,j,k]
	//   lap_j = A[i,j+1,k] - 2*A[i,j,k] + A[i,j-1,k]
	//   lap_k = A[i,j,k+1] - 2*A[i,j,k] + A[i,j,k-1]
	//   B = 0.125*(lap_i + lap_j + lap_k) + A
	//
	// This can be rearranged to:
	//   sum_nbr = sum of 6 direct neighbors
	//   B = 0.125 * sum_nbr + 0.25 * center
	const num_t w_center    = num_t(0.25);  // 1 - 6 * 0.125
	const num_t w_neighbor  = num_t(0.125);

	#pragma scop
	traverser(A, B)
		.order(time_bcast)
		.template for_dims<'t'>([=](auto t_trav) {
			// t_trav has 't' fixed; spatial dimensions are still i, j, k.
			// Restrict to the interior once per time step.
			auto inner = t_trav.order(interior);

			// -----------------------------------------------------------------
			// First sweep: update B from A
			// -----------------------------------------------------------------
			inner.for_each([=](auto state) {
				// state contains 'i', 'j', 'k', and 't' (ignored by A/B).
				const num_t center = A[state];

				// Load 6 neighbors explicitly; this layout makes data dependencies
				// clear and encourages the compiler to vectorize over the
				// innermost (contiguous) 'k' dimension.
				const num_t ip = A[state + di];
				const num_t im = A[state - di];
				const num_t jp = A[state + dj];
				const num_t jm = A[state - dj];
				const num_t kp = A[state + dk];
				const num_t km = A[state - dk];

				const num_t neighbor_sum = ip + im + jp + jm + kp + km;

				// Equivalent to the original 7-point stencil, but with fewer
				// multiplications and an explicit neighbor sum.
				B[state] = w_center * center + w_neighbor * neighbor_sum;
			});

			// -----------------------------------------------------------------
			// Second sweep: update A from B
			// -----------------------------------------------------------------
			inner.for_each([=](auto state) {
				const num_t center = B[state];

				const num_t ip = B[state + di];
				const num_t im = B[state - di];
				const num_t jp = B[state + dj];
				const num_t jm = B[state - dj];
				const num_t kp = B[state + dk];
				const num_t km = B[state - dk];

				const num_t neighbor_sum = ip + im + jp + jm + kp + km;

				A[state] = w_center * center + w_neighbor * neighbor_sum;
			});
		});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	int n = N;
	int tsteps = TSTEPS;

	// set lengths for spatial dimensions
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n) ^
		noarr::set_length<'k'>(n);

	// allocate A and B
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(n, A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_heat_3d(tsteps, n, A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
