using num_t = DATA_TYPE;

namespace {

// Spatial layout: A and B are 3D: i x j x k, with k the innermost (contiguous) dimension
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// i is the outermost, k is the innermost (contiguous) dimension
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ j_vec ^ i_vec);
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ j_vec ^ i_vec);
} tuning;

// initialization function
void init_array(int n, auto A, auto B) {
	// A, B: i x j x k, all dimensions of length n
	using namespace noarr;

	// Precompute the scaling factor once instead of dividing in every iteration:
	//   original: (i + j + (n - k)) * 10 / n
	//   now:      (i + j + (n - k)) * (10 / n)
	const num_t scale = num_t(10) / num_t(n);

	traverser(A, B).for_each([=](auto state) {
		auto [i, j, k] = get_indices<'i', 'j', 'k'>(state);

		num_t value = num_t(i + j + (n - k)) * scale;

		A[state] = value;
		B[state] = value;
	});
}

// computation kernel
//
// The numerical scheme is identical to the reference:
// for each time step t:
//   1) B <- stencil(A)
//   2) A <- stencil(B)
//
// We keep the layout i x j x k with k contiguous and use Noarr traversers for
// the 3D spatial loops. The time loop is expressed as a broadcast dimension 't'
// so that all data-parallel work is still driven by Noarr.
//
// Micro-optimizations:
//   * Precompute neighbor index states (di, dj, dk) once per call.
//   * Precompute constants (alpha = 0.125, two = 2.0) once.
//   * Reuse 2 * center within each stencil update.
// These do not change the mathematical expression, only reduce redundant work.
[[gnu::flatten, gnu::noinline]]
void kernel_heat_3d(int tsteps, int n, auto A, auto B) {
	using namespace noarr;

	// Offsets for 6-point stencil in each spatial dimension
	const auto di = idx<'i'>(1);
	const auto dj = idx<'j'>(1);
	const auto dk = idx<'k'>(1);

	// Stencil coefficients
	constexpr num_t alpha = num_t(0.125); // diffusion weight
	constexpr num_t two   = num_t(2.0);   // central second derivative coeff

	// Interior region: i, j, k in [1, n-2]
	auto interior =
		noarr::slice<'i'>(1, n - 2) ^
		noarr::slice<'j'>(1, n - 2) ^
		noarr::slice<'k'>(1, n - 2);

	// Time "dimension" using broadcast: repeats the same spatial domain tsteps times
	auto time_bcast = noarr::bcast<'t'>(tsteps);

	#pragma scop
	traverser(A, B)
		// add the time broadcast dimension 't'
		.order(time_bcast)
		// iterate time steps as the outermost loop
		.template for_dims<'t'>([=](auto t_trav) {
			// t_trav has 't' fixed; we ignore 't' when indexing A and B
			auto inner = t_trav.order(interior);

			// -----------------------------------------------------------------
			// First sweep: update B from A (Jacobi-like update)
			// -----------------------------------------------------------------
			inner.for_each([=](auto state) {
				// state contains 'i', 'j', 'k', and 't' (ignored for A/B indexing)

				const num_t center     = A[state];
				const num_t two_center = two * center;

				// 6 neighbors in i, j, k directions
				const num_t lap_i = A[state + di] - two_center + A[state - di];
				const num_t lap_j = A[state + dj] - two_center + A[state - dj];
				const num_t lap_k = A[state + dk] - two_center + A[state - dk];

				// Keep the same algebraic form as the reference implementation:
				B[state] = alpha * lap_i
				         + alpha * lap_j
				         + alpha * lap_k
				         + center;
			});

			// -----------------------------------------------------------------
			// Second sweep: update A from B, using the freshly computed B
			// -----------------------------------------------------------------
			inner.for_each([=](auto state) {
				const num_t center     = B[state];
				const num_t two_center = two * center;

				const num_t lap_i = B[state + di] - two_center + B[state - di];
				const num_t lap_j = B[state + dj] - two_center + B[state - dj];
				const num_t lap_k = B[state + dk] - two_center + B[state - dk];

				A[state] = alpha * lap_i
				         + alpha * lap_j
				         + alpha * lap_k
				         + center;
			});
		});
	#pragma endscop
}

} // namespace

